*{box-sizing:border-box}
body{margin:0;background:radial-gradient(ellipse at 48% -14%,#49323c 0,#21171f 39%,#100d12 76%);color:var(--text);font-family:'DM Sans',sans-serif;min-height:100vh}
button{font:inherit;color:inherit;cursor:pointer}
button:focus-visible{outline:2px solid var(--gold);outline-offset:3px}
.app{max-width:1450px;margin:auto;padding:21px 30px 34px}
.topbar{height:60px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff15;margin-bottom:24px}
.brand{display:flex;align-items:center;gap:12px;font-family:Cinzel,serif;font-size:19px;letter-spacing:2px;font-weight:700}
.brand-mark{width:37px;height:37px;border:1px solid #80666f;border-radius:50%;display:grid;place-items:center;color:var(--gold);font-size:21px;box-shadow:0 0 25px #c88b6040}
.top-meta{display:flex;gap:10px;align-items:center}
.pill{border:1px solid var(--line);border-radius:4px;padding:8px 12px;color:#c5b7bf;font-size:12px;letter-spacing:.5px}
.pill strong{color:var(--gold);font-weight:600}
.reset{background:transparent;border:0;color:#9e8f99;font-size:12px;padding:8px}
.layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:22px;align-items:start}
.left{min-width:0}
.eyebrow{font-size:10px;letter-spacing:2.4px;color:var(--gold);text-transform:uppercase;font-weight:700}
.title-row{display:flex;justify-content:space-between;align-items:end;margin:0 0 16px}
.title{font-family:Cinzel,serif;font-size:29px;font-weight:500;letter-spacing:.6px;margin:6px 0 0}
.subtitle{font-size:13px;color:var(--muted);margin:7px 0 0}
.stage-label{text-align:right;font-size:11px;color:#ae9da8;letter-spacing:1px}
.stage-label strong{display:block;color:var(--gold);font-size:14px;margin-top:5px}
.battle-wrap{border:1px solid #5b414b;background:#141116;padding:8px;box-shadow:0 20px 70px #0007;position:relative}
.battle-wrap:before{content:'';position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,#a74b3710,transparent 65%)}
.board{position:relative;display:grid;grid-template-columns:repeat(7,minmax(45px,1fr));grid-template-rows:repeat(5,minmax(64px,1fr));gap:5px;aspect-ratio:1.55}
.tile{position:relative;border:1px solid #3e3038;background:linear-gradient(145deg,#282027,#1d181d);min-width:0;display:grid;place-items:center;transition:.15s;overflow:hidden}
.tile:after{content:'';position:absolute;inset:0;background:radial-gradient(circle at 50% 50%,transparent 30%,#0002 100%);pointer-events:none}
.tile:hover{border-color:#9c7987;background-color:#382931}
.tile.selected{border-color:var(--gold);box-shadow:inset 0 0 0 1px #d8b77560,0 0 12px #d8b77535}
.tile.valid{border-color:#85b89a;background:#28392f;cursor:pointer}
.tile.target{border-color:#d77771;background:#442727;cursor:crosshair}
.tile.terrain{background-color:#16171a}
.ground-mark{position:absolute;color:#74606a;font-size:14px;opacity:.38}
.ground-mark.a{top:8px;left:8px}
.ground-mark.b{right:7px;bottom:5px;transform:rotate(45deg)}
.entity{z-index:2;display:flex;flex-direction:column;align-items:center;gap:2px}
.sprite{font-size:30px;line-height:1;text-shadow:0 3px 8px #000;filter:drop-shadow(0 3px 5px #0008)}
.entity-name{font-family:Cinzel,serif;font-size:8px;letter-spacing:.4px;color:#eee0de;white-space:nowrap}
.hp{height:4px;width:39px;background:#33242a;border:1px solid #050405;border-radius:3px;overflow:hidden;margin-top:1px}
.hp i{display:block;height:100%;background:#a7c488}
.enemy .hp i{background:#cd7770}
.entity.ready .sprite{filter:drop-shadow(0 0 8px #cbb27b)}
.corpse{position:absolute;color:#b57776;font-size:18px;opacity:.62;z-index:1}
.cell-coord{position:absolute;left:4px;top:3px;color:#ffffff17;font-size:8px}
.board-caption{display:flex;justify-content:space-between;padding:9px 5px 1px;font-size:10px;letter-spacing:.8px;color:#91818b;text-transform:uppercase}
.turn-banner{color:var(--gold)}
.below{display:grid;grid-template-columns:minmax(0,1fr) 250px;gap:14px;margin-top:14px}
.action-panel,.objective{border:1px solid var(--line);background:#19151a;padding:14px}
.panel-heading{font-family:Cinzel,serif;font-size:12px;letter-spacing:1.1px;color:#e0d1d1;margin-bottom:11px;display:flex;justify-content:space-between}
.panel-heading small{font-family:'DM Sans',sans-serif;letter-spacing:0;color:var(--muted);font-size:10px}
.actions{display:flex;flex-wrap:wrap;gap:8px}
.action{border:1px solid #58434e;background:#28212a;padding:9px 12px;border-radius:3px;font-size:11px;font-weight:600;letter-spacing:.25px;transition:.15s}
.action:hover:not(:disabled){background:#403242;border-color:#a47e94;transform:translateY(-1px)}
.action.primary{background:#4b332d;border-color:#8e644f;color:#f1d7b4}
.action.end{margin-left:auto;background:#76523b;border-color:#b08358;color:#fff0d6}
.action:disabled{opacity:.42;cursor:not-allowed}
.action .cost{color:#d8b775;margin-left:4px;font-size:10px}
.selection-hint{color:#a897a2;font-size:11px;line-height:1.6;min-height:17px;margin-top:10px}
.objective{padding:13px 15px}
.objective p{font-size:11px;color:#b3a5ab;line-height:1.55;margin:0}
.objective strong{color:#ead9d4}
.obj-row{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #ffffff12;margin-top:11px;padding-top:10px;font-size:10px;color:#aa9ba4}
.obj-row b{color:var(--mint);font-size:11px}
.side{display:flex;flex-direction:column;gap:14px}
.side-card{border:1px solid var(--line);background:linear-gradient(145deg,#211a22,#181419);padding:17px}
.side-card h3{font-family:Cinzel,serif;font-size:13px;font-weight:500;letter-spacing:1.1px;margin:0 0 15px;color:#eadada}
.hero{display:flex;align-items:center;gap:13px}
.hero-portrait{height:54px;width:54px;border:1px solid #6b5260;background:radial-gradient(circle,#503644,#211a24);display:grid;place-items:center;font-size:30px}
.hero-info strong{display:block;font-family:Cinzel,serif;font-size:13px;font-weight:500}
.hero-info span{font-size:10px;color:#a894a1;display:block;margin-top:4px}
.statline{display:flex;justify-content:space-between;font-size:10px;color:#bbaeb6;margin-top:15px}
.statline strong{color:#f3e7e5;font-size:11px}
.bar{height:6px;background:#35262d;margin-top:6px;overflow:hidden}
.bar i{display:block;height:100%;background:linear-gradient(90deg,#a2505b,#d27b75);transition:width .25s}
.bar.mana i{background:linear-gradient(90deg,#65558d,#ad8bd1)}
.relics{display:flex;gap:7px;margin-top:14px}
.relic{flex:1;background:#171319;border:1px solid #372c36;padding:8px 5px;text-align:center;color:#cfba8b;font-size:19px}
.relic small{display:block;color:#a2939c;font-size:8px;letter-spacing:.4px;margin-top:4px}
.log{height:177px;overflow:auto;display:flex;flex-direction:column;gap:8px;padding-right:3px}
.logline{font-size:10px;line-height:1.45;color:#ae9fa7;border-left:2px solid #624b5a;padding-left:8px}
.logline.good{border-color:#7caf92;color:#bad7c3}
.logline.warn{border-color:#ce7771;color:#e0aaa1}
.logline.gold{border-color:var(--gold);color:#e1c794}
.campaign{display:flex;justify-content:space-between;gap:8px;margin-top:14px}
.chapter{height:5px;flex:1;background:#44343e;position:relative}
.chapter.done{background:var(--gold)}
.chapter.active{background:#9e7057;box-shadow:0 0 8px #d8b77566}
.chapter-labels{display:flex;justify-content:space-between;color:#847680;font-size:8px;margin-top:7px}
.overlay{position:fixed;inset:0;background:#0b080bd9;z-index:10;display:grid;place-items:center;padding:20px;backdrop-filter:blur(5px)}
.modal{max-width:530px;width:100%;border:1px solid #806170;background:linear-gradient(145deg,#281d29,#151117);padding:34px;text-align:center;box-shadow:0 20px 90px #000b}
.modal-icon{font-size:46px;color:var(--gold);margin-bottom:10px}
.modal h1{font-family:Cinzel,serif;letter-spacing:2px;font-weight:500;font-size:26px;margin:4px 0 10px}
.modal p{font-size:13px;color:#b9aab2;line-height:1.7}
.modal .action{margin-top:15px;padding:12px 20px}
.modal .rules{display:grid;grid-template-columns:1fr 1fr;gap:8px;text-align:left;margin:18px 0;color:#beafb5;font-size:11px}
.rules span{border:1px solid #40323e;background:#18141a;padding:10px}
.rules b{color:var(--gold)}
.hidden{display:none!important}
.toast{position:fixed;left:50%;bottom:22px;transform:translateX(-50%);background:#2c232c;border:1px solid #715264;color:#e8d6d5;padding:11px 18px;font-size:12px;z-index:20;box-shadow:0 8px 28px #0009;animation:fade 2.4s forwards}
@keyframes fade{0%,75%{opacity:1}
100%{opacity:0;visibility:hidden}
}
@media(max-width:980px){.layout{grid-template-columns:minmax(0,1fr) 270px}
.below{grid-template-columns:1fr}
.objective{display:none}
.board{grid-template-rows:repeat(5,minmax(58px,1fr));gap:4px}
.app{padding:15px 18px}
}
@media(max-width:700px){.app{padding:12px 11px 22px}
.topbar{margin-bottom:17px}
.brand{font-size:15px}
.pill{padding:7px 8px;font-size:10px}
.layout{grid-template-columns:1fr}
.side{display:grid;grid-template-columns:1fr 1fr}
.side-card:first-child{grid-row:span 2}
.log{height:125px}
.title{font-size:23px}
.board{grid-template-rows:repeat(5,minmax(54px,1fr));gap:3px}
.battle-wrap{padding:5px}
.sprite{font-size:25px}
.entity-name{font-size:7px}
.below{margin-top:9px}
.action-panel{padding:12px}
.action.end{margin-left:0}
.actions{gap:6px}
.action{padding:8px 9px;font-size:10px}
.stage-label{font-size:9px}
.stage-label strong{font-size:12px}
}
@media(max-width:420px){.side{grid-template-columns:1fr}
.side-card:first-child{grid-row:auto}
.log{height:95px}
.board{grid-template-columns:repeat(7,minmax(0,1fr));grid-template-rows:repeat(5,minmax(45px,1fr))}
.entity-name{display:none}
.hp{width:28px}
.sprite{font-size:21px}
.brand-mark{height:31px;width:31px}
.top-meta{gap:3px}
.reset{font-size:10px}
}
@media(max-width:360px){.brand{gap:6px;font-size:12px;letter-spacing:1px}
.brand-mark{height:28px;width:28px}
.pill{padding:6px 5px;font-size:9px}
.top-meta{gap:2px}
.reset{padding:5px 3px;max-width:42px}
}

