const fs=require('fs');
const html='file:///home/runner/work/PlayGround/PlayGround/index.html';
(async()=>{
 const targets=await (await fetch('http://127.0.0.1:9222/json')).json();
 const t=targets.find(x=>x.url==='about:blank'); const ws=new WebSocket(t.webSocketDebuggerUrl);
 await new Promise((res,rej)=>{ws.onopen=res;ws.onerror=rej}); let seq=0, pending=new Map(), errors=[];
 ws.onmessage=e=>{let m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
 const send=(method,params={})=>new Promise(r=>{let id=++seq;pending.set(id,r);ws.send(JSON.stringify({id,method,params}))});
 const evaljs=async expression=>(await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true})).result.result.value;
 await send('Page.enable');await send('Runtime.enable');await send('Page.navigate',{url:html}); await new Promise(r=>setTimeout(r,700));
 let first=await evaljs(`({title:document.title,stage:document.querySelector('#stageCount').textContent,board:document.querySelectorAll('.tile').length,choices:[...document.querySelectorAll('#actions .action')].map(x=>x.textContent.trim()),intro:!document.querySelector('#intro').classList.contains('hidden')})`);
 await evaljs(`document.querySelector('#beginBtn').click()`);
 let summoned=await evaljs(`({options:[...document.querySelectorAll('#actions .action')].map(x=>x.textContent.trim()),mode:JSON.parse(localStorage.getItem('gravebound-save')).mode})`);
 const state={stage:0,round:1,essence:4,maxEssence:8,hp:12,maxHp:12,level:1,relic:'',boons:[],rewardChoices:[],chosenBoon:'',allies:[{id:1,name:'Morwen',icon:'🧙🏻‍♀️',type:'hero',hp:12,max:12,atk:3,x:0,y:2,acted:true},{id:2,name:'Skeleton',icon:'💀',type:'skeleton',hp:5,max:5,atk:2,range:1,x:1,y:2,acted:true}],enemies:[{id:100,name:'Test Foe',icon:'👹',type:'enemy',hp:2,max:2,atk:4,x:2,y:2,range:1,acted:false}],corpses:[],selected:1,mode:'play',log:[]};
 await evaljs(`localStorage.setItem('gravebound-save',${JSON.stringify(JSON.stringify(state))});location.reload()`);await new Promise(r=>setTimeout(r,500));
 let pre=await evaljs(`({stage:document.querySelector('#stageTitle').textContent,mode:JSON.parse(localStorage.getItem('gravebound-save')).mode})`);
 let victory=await evaljs(`document.querySelector('#actions .end')?.click();true`);await new Promise(r=>setTimeout(r,50));
 let final=await evaljs(`({mode:JSON.parse(localStorage.getItem('gravebound-save')).mode,hp:JSON.parse(localStorage.getItem('gravebound-save')).hp,foes:JSON.parse(localStorage.getItem('gravebound-save')).enemies.length,dialog:!document.querySelector('#result').classList.contains('hidden'),result:document.querySelector('#resultTitle').textContent,log:JSON.parse(localStorage.getItem('gravebound-save')).log.slice(0,4).map(x=>x.text)})`);
 console.log(JSON.stringify({first,summoned,pre,final,errors},null,2));ws.close();
})().catch(e=>{console.error(e);process.exit(1)});
