+.ready .sprite{filter:drop-shadow(0 0 9px #e1c17d9c)}
+.ally .entity-name{color:#d8d0bb}
+.enemy .entity-name{color:#e8c4bb}
+.hp{width:44px;height:5px}
+.board-caption{padding:11px 6px 2px;letter-spacing:1.1px}
+.turn-banner{font-weight:700}
