.entity{position:relative}.entity.striking .sprite{animation: lunge .34s ease-out}.entity.hurt .sprite{animation: recoil .34s ease-out}.entity .impact{position:absolute;left:50%;top:-9px;white-space:nowrap;pointer-events:none;font-size:12px;font-weight:800;color:#ffe4aa;text-shadow:0 2px 6px #000,0 0 12px #f4a35a;animation:impact-rise .82s ease-out forwards;z-index:5}.entity .impact.magic{color:#d8b8ff;text-shadow:0 2px 6px #000,0 0 12px #a88bd0}.entity .impact.guard{color:#bcebd3;text-shadow:0 2px 6px #000,0 0 12px #78d5a5}.entity .impact.damage{color:#ffaaa0}.entity-trait{font-size:7px;line-height:1;color:#d9bd86;letter-spacing:.25px;text-shadow:0 1px 5px #000;white-space:nowrap}.entity.ghoul .sprite{filter:drop-shadow(0 0 7px #b6d76a88)}.entity.wraith .sprite{filter:drop-shadow(0 0 8px #b99be7aa)}.entity.skeleton .sprite{filter:drop-shadow(0 0 7px #d7d0bc77)}.entity.hurt{z-index:4}.action:active:not(:disabled){transform:translateY(1px)}
@keyframes lunge{45%{transform:translateX(7px) scale(1.16)}100%{transform:translateX(0) scale(1)}}@keyframes recoil{25%{transform:translateX(-5px);filter:brightness(2)}60%{transform:translateX(4px)}100%{transform:translateX(0)}}@keyframes impact-rise{0%{opacity:0;transform:translate(-50%,7px) scale(.7)}18%{opacity:1;transform:translate(-50%,-4px) scale(1.12)}100%{opacity:0;transform:translate(-50%,-27px) scale(1)}}

